<script setup lang="ts">
import { ref, onMounted, computed } from 'vue'
import { Copy, QrCode, RefreshCw, Cable, ShieldCheck, ArrowDownToLine, Globe2, Info, X, Eye, EyeOff } from 'lucide-vue-next'
import QRCode from 'qrcode'
import { api, run, copy, activeJob, snapshot, toast, stateLabel } from '../store'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import NodeStatsList from '../components/NodeStatsList.vue'
import StatusBadge from '../components/StatusBadge.vue'
interface Exports { subscription: string; mihomo: string; direct: string; nodes: { name: string; protocol: string; value: string }[]; telegram: string }
const data = ref<Exports>(), failure = ref(''), busy = ref(true), format = ref('mihomo'), qr = ref(''), qrTitle = ref(''), showSecrets = ref(false), confirm = ref(false)
const url = computed(() => data.value?.[format.value as 'subscription' | 'mihomo' | 'direct'] || '')
const qrDialog = ref<HTMLDialogElement>(), qrClose = ref<HTMLButtonElement>()
let previous: HTMLElement | null = null
async function load() { busy.value = true; failure.value = ''; try { data.value = await api<Exports>('/nodes') } catch (e) { failure.value = (e as Error).message } finally { busy.value = false } }
async function showQr(value: string, title: string) {
  try { qr.value = await QRCode.toDataURL(value, { width: 280, margin: 3, errorCorrectionLevel: 'M' }); qrTitle.value = title; previous = document.activeElement as HTMLElement; qrDialog.value?.showModal(); qrClose.value?.focus() }
  catch { toast('二维码生成失败，请直接复制链接。') }
}
function closeQr() { qrDialog.value?.close(); previous?.focus() }
function download() {
  if (!data.value) return
  const blob = new Blob([data.value.nodes.map(n => n.value).join('\n')], { type: 'text/plain;charset=utf-8' })
  const objectUrl = URL.createObjectURL(blob), a = document.createElement('a')
  a.href = objectUrl; a.download = 'xray-nodes.txt'; a.click(); URL.revokeObjectURL(objectUrl)
}
async function updateExports() { confirm.value = false; const job = await run('export'); if (job) toast('导出任务已开始；完成后点击“重新读取”。') }
async function installTelegram() { await run('mtproto') }
async function restartTelegram() { await run('mtproto-restart') }
onMounted(load)
</script>
<template>
  <div class="page"><div class="page-heading"><div><h1>节点与订阅</h1><p>一个订阅，连接你的设备。链接内包含密钥，请妥善保管。</p></div><div class="heading-actions"><button class="button secondary" :disabled="busy" @click="load"><RefreshCw :size="16" :class="{ spin: busy }" />重新读取</button><button class="button primary" :disabled="!!activeJob || !snapshot?.installed" @click="confirm = true"><RefreshCw :size="16" />更新导出</button></div></div>
    <div v-if="failure" class="notice-box error-box" role="alert">{{ failure }}<button class="button secondary" @click="load">重试</button></div><div v-else-if="busy" class="empty-state"><RefreshCw class="spin" /><p>正在读取节点配置…</p></div>
    <template v-else-if="data"><section class="panel subscription-panel"><div class="panel-title"><div class="section-heading"><span class="subscription-symbol"><Cable :size="23" /></span><div><h2>你的专属订阅</h2><p>推荐通过 Cloudflare HTTPS 订阅导入客户端。</p></div></div><span class="private-label"><ShieldCheck :size="15" />私密链接</span></div><div class="tabs" role="tablist" aria-label="订阅格式"><button v-for="item in [{ id: 'mihomo', name: 'Clash / Mihomo' }, { id: 'subscription', name: '通用订阅' }, { id: 'direct', name: '直连备用' }]" :id="'tab-' + item.id" :key="item.id" role="tab" :aria-selected="format === item.id" aria-controls="subscription-tabpanel" :tabindex="format === item.id ? 0 : -1" :class="{ selected: format === item.id }" @click="format = item.id" @keydown.right.prevent="format = ['mihomo','subscription','direct'][(['mihomo','subscription','direct'].indexOf(format) + 1) % 3]!; ($event.currentTarget as HTMLElement).parentElement?.querySelector<HTMLButtonElement>('#tab-' + format)?.focus()" @keydown.left.prevent="format = ['mihomo','subscription','direct'][(['mihomo','subscription','direct'].indexOf(format) + 2) % 3]!; ($event.currentTarget as HTMLElement).parentElement?.querySelector<HTMLButtonElement>('#tab-' + format)?.focus()">{{ item.name }}</button></div><div id="subscription-tabpanel" role="tabpanel" :aria-labelledby="'tab-' + format"><div v-if="url" class="subscription-url"><code :class="{ 'secret-mask': !showSecrets }">{{ showSecrets ? url : url.replace(/\/[^/?]+(?=\?|$)/, '/••••••••••••••••••••') }}</code><button class="icon-button" :aria-label="showSecrets ? '隐藏链接密钥' : '显示完整链接'" @click="showSecrets = !showSecrets"><component :is="showSecrets ? EyeOff : Eye" :size="18" /></button></div><div v-else class="inline-empty">暂无可用订阅，请先安装节点并更新导出。</div><div class="subscription-actions"><button class="button primary" :disabled="!url" @click="copy(url)"><Copy :size="16" />复制订阅地址</button><button class="button secondary" :disabled="!url" @click="showQr(url, '订阅二维码')"><QrCode :size="17" />显示二维码</button><span v-if="format === 'direct'" class="field-hint">备用地址使用 HTTP，仅通过可信网络获取。</span><span v-else class="field-hint">适用于支持对应订阅格式的客户端</span></div></div></section>
    <NodeStatsList />
    <div class="section-bar"><h2>节点链接 <span class="count-label">{{ data.nodes.length }}</span></h2><button class="text-link" :disabled="!data.nodes.length" @click="download"><ArrowDownToLine :size="15" />导出节点文件</button></div><section class="panel node-list"><div v-for="node in data.nodes" :key="node.name" class="node-row"><span class="service-icon" :class="node.name === 'Hy2' ? 'hy2' : node.name === 'CF' ? 'cloudflare' : 'xray'"><Globe2 :size="21" /></span><div><h3>{{ node.name === 'CF' ? 'Cloudflare' : node.name === 'Hy2' ? 'Hysteria 2' : 'REALITY' }}</h3><p>{{ node.protocol }}</p></div><span class="node-endpoint mono">{{ node.name === 'CF' ? snapshot?.settings.cf_entry : snapshot?.settings.server }}</span><div class="node-actions"><button class="icon-button" :aria-label="'复制 ' + node.name + ' 节点'" @click="copy(node.value)"><Copy :size="17" /></button><button class="icon-button" :aria-label="'显示 ' + node.name + ' 二维码'" @click="showQr(node.value, node.name + ' 节点')"><QrCode :size="18" /></button></div></div><div v-if="!data.nodes.length" class="empty-state"><Cable :size="30" /><h3>还没有节点</h3><p>完成部署后，节点会出现在这里。</p><RouterLink to="/install" class="button primary">前往部署</RouterLink></div></section>
    <section class="panel telegram-panel telegram-card"><div class="telegram-card-top"><div class="telegram-card-identity"><span class="service-icon mtproto"><ShieldCheck :size="21" /></span><div><h2>Telegram MTProto</h2><p>Telegram 专用代理 · TCP {{ snapshot?.services.find(s => s.id === 'mtproto')?.port?.replace('TCP ', '') || '53528' }}</p></div></div><StatusBadge :state="snapshot?.services.find(s => s.id === 'mtproto')?.state || 'missing'" /></div><div class="telegram-card-metrics"><div><span>连接方式</span><strong>MTProto</strong></div><div><span>节点地址</span><strong class="mono">{{ snapshot?.settings.server || '未配置' }}</strong></div><div><span>当前状态</span><strong>{{ stateLabel(snapshot?.services.find(s => s.id === 'mtproto')?.state || 'missing') }}</strong></div></div><div class="telegram-card-actions"><template v-if="data.telegram"><button class="button secondary small" @click="copy(data.telegram)"><Copy :size="15" />复制 TG 链接</button><button class="button secondary small" @click="showQr(data.telegram, 'Telegram 代理')"><QrCode :size="15" />二维码</button></template><button v-else class="button primary small" :disabled="!!activeJob || !snapshot?.installed" @click="installTelegram"><ShieldCheck :size="15" />安装 TG 代理</button><button v-if="snapshot?.services.find(s => s.id === 'mtproto')?.state !== 'missing'" class="button secondary small" :disabled="!!activeJob" @click="restartTelegram"><RefreshCw :size="15" />重启 TG</button></div><p v-if="!data.telegram" class="field-hint telegram-empty-hint">安装后回到本页重新读取，即可显示 TG 一键链接与二维码。</p></section><div class="overview-note"><Info :size="16" />重建临时隧道可能改变订阅域名，请在操作完成后重新获取订阅地址。</div></template>
    <dialog ref="qrDialog" class="qr-dialog" aria-labelledby="qr-title" @cancel.prevent="closeQr" @click="e => { if (e.target === qrDialog) closeQr() }"><div class="panel-title"><h2 id="qr-title">{{ qrTitle }}</h2><button ref="qrClose" class="icon-button" aria-label="关闭二维码" @click="closeQr"><X :size="20" /></button></div><img :src="qr" :alt="qrTitle" width="280" height="280" /><p>请使用客户端扫码，请勿分享截图。</p></dialog>
    <ConfirmDialog :open="confirm" title="更新节点与订阅导出？" message="读取当前隧道域名，重新生成节点链接和订阅文件。完成后点击“重新读取”加载最新结果。" @close="confirm = false" @confirm="updateExports" />
  </div>
</template>
